<template>
    <Liquid v-if="conditionLiquid?.start && exporting" :data="conditionLiquid.start"></Liquid>
    <div
        v-bind="blockAttrs"
        @mouseenter="overBlock"
        @mouseleave="outBlock"
        @mousedown.stop="dragBlock"
        @click.stop="activeBlock"
        @contextmenu.stop="rightClickMenu"
        @mousemove="onBlockMouseMove"
        :class="{ 'ecom_current-edit': !exporting && isEditing, 'ecom-current-column-drag': isDragColumn }"
    >
        <div
            v-if="!exporting && !inGroup && canDrop"
            class="drop__block--placeholder ecom-placeholder-top"
            :class="[
                'drop__block_' + index,
                { 'ecom-current-block-drag': placeholderTop, 'ecom-drag-current': currentDrag },
                checkInGridDrop ? 'ecom-cant-drop' : ''
            ]"
            @mouseenter="overBlock"
            @mouseleave="outBlock"
        >
            <div class="drop__block--placeholder-body drop__block--placeholder__top"></div>
        </div>
        <Row
            v-if="block.row"
            :section_id="section_id"
            ref="blockElement"
            :data="block.row"
            :deep="deep + 1"
            :index="index"
            :breadcrumb="`${breadcrumb}/${data?.id}`"
            :dragParent="dragParent"
        />
        <component
            :is="block.group.element + 'Element'"
            v-else-if="block.group"
            ref="blockElement"
            :data="block.group"
            :key="refreshKey"
            :deep="deep"
            :index="index"
            :breadcrumb="!exporting ? `${breadcrumb}/${data?.id}` : null"
        />
        <template v-else>
            <component
                :section_id="section_id"
                :is="checkExtensionNotInstall ? checkExtensionNotInstall : block.name + 'Element'"
                ref="blockElement"
                :key="refreshKey"
                :data="block"
                :deep="deep"
                :breadcrumb="!exporting ? `${breadcrumb}/${data?.id}` : null"
            />
        </template>
        <div
            v-if="isEditing && !exporting && !isFullScreen"
            class="ecom-resize-flexbox"
            @mousedown.stop="startDragResize($event, 'custom-width', $refs.wrapper, 'block', 'right')"
        >
            <span v-if="dragResize.isActive && dragResize.direction !== 'left'">
                {{ dragResize.finalWidth }}
            </span>
        </div>
        <div
            v-if="isEditing && !exporting && !isFullScreen"
            class="ecom-resize-flexbox ecom-resize-left"
            @mousedown.stop="startDragResize($event, 'custom-width', $refs.wrapper, 'block', 'left')"
        >
            <span v-if="dragResize.isActive && dragResize.direction === 'left'">
                {{ dragResize.finalWidth }}
            </span>
        </div>
        <div
            v-if="isEditing && !block.row && !exporting && !isFullScreen"
            class="core__block--padding-top core__block--padding top-0"
            @mousedown.stop="startDragPadding($event, 'top')"
        >
            <span
                v-if="isDrag && paddingPosition == 'top'"
                class="core__block--padding-markup top-0"
                :style="{ height: paddingCurrentVal + 'px' }"
            >
                <span
                    v-if="paddingPosition == 'top' && isDrag"
                    class="core__block--padding-value"
                    v-html="paddingCurrentVal + 'px'"
                />
            </span>
        </div>
        <div
            v-if="isEditing && !block.row && !exporting && !isFullScreen"
            class="core__block--padding-bottom core__block--padding bottom-0"
            @mousedown.stop="startDragPadding($event, 'bottom')"
        >
            <span
                v-if="isDrag && paddingPosition == 'bottom'"
                class="core__block--padding-markup"
                :style="{ height: paddingCurrentVal + 'px' }"
            >
                <span
                    v-if="paddingPosition == 'bottom' && isDrag"
                    class="core__block--padding-value"
                    v-html="paddingCurrentVal + 'px'"
                />
            </span>
        </div>
        <div
            v-if="!exporting && !inGroup && canDrop"
            :class="{
                'ecom-current-block-drag': (placeholderBottom || (isPlaceholderVisible && !exporting)),
                'ecom-drag-current': currentDrag,
                'ecom-cant-drop': checkInGridDrop
            }"
            class="drop__block--placeholder ecom-placeholder-bottom"
            @mouseenter="overBlock"
        >
            <div class="drop__block--placeholder-body drop__block--placeholder__bottom"></div>
        </div>
    </div>
    {{ exporting === true && conditionLiquid?.start ? conditionLiquid?.end : "" }}
</template>

<script lang="ts">
import { Core, Liquid, blockMixin, DragResize } from "@/mixins";
import { allComponents, componentName, getIdParentAndIndex, loadComponent } from "@/utils/helpers";
import { elementIframe } from "./configElement";
export default {
    name: "Block",
    mixins: [Core, Liquid, blockMixin, DragResize],
    components: {
        ...allComponents()
    },
    emits: ["update-size"],
    props: {
        data: {
            type: Object,
            default() {
                return {
                    name: "empty"
                };
            }
        },
        deep: {
            type: Number,
            default: 0
        },
        index: {
            type: Number,
            default: 0
        },
        control: {
            type: Boolean,
            default: true
        },
        gindex: {
            type: Number,
            default: 0
        },
        section_id: {
            type: String,
            default: ""
        },
        breadcrumb: {
            type: String,
            default: ""
        },
        dragParent: {
            type: Boolean,
            default: false
        },
        hidden: {
            type: Boolean,
            default: false
        },
        isFlexContainer: {
            type: Boolean,
            default: false
        },
        isParentRow: {
            type: Boolean,
            default: false
        },
    },

    data(): object {
        return {
            is: "block",
            name: this.data.row ? "inner row" : this.data.group ? this.data.group.element : "block",
            elementIframe,
            over: false,
            dragging: false,
            placeholder: "top",
            refreshKey: "",
            isMounted: false,
            isDrag: false,
            space: 0,
            position: 0,
            paddingCurrentVal: 0,
            paddingPosition: "",
            initInGrid: false,
            canSetTempBlockNull: false,
            mousePosition: { x: 0, y: 0 },
            blockRect: null,
            dragPosition: "top", // 'top' hoặc 'bottom'
        };
    },

    computed: {
        isDragging() {
            return this.$store.getters["builder/isDragging"];
        },
        isDragColumn() {
            return this.dragCurrent?.is === "column" && this.dragCurrent?.section_id === this.section_id;
        },
        checkInGridDrop() {
            return !this.$helpers.checkGridDrop(this.dragCurrent, this);
        },
        isPlaceholderVisible() {
            return this.isLast && this.$parent?.$parent?.$parent?.is == 'section' && this?.dropTo?.data.id === this.section_id && this.dropTo?.is === 'section';
        },
        checkExtensionNotInstall() {
            const itemName = componentName(this.data.name) + "Element";
            return Object.keys(allComponents()).includes(itemName)
                ? ""
                : "PlaceholderExtensionElement";
        },
        stack() {
            return this.$parent.$parent.blocks;
        },
        width_mb() {
            return this.data?.advanced?.["custom-width__mobile"] || this.data?.advanced?.['width-max'] === 'unset';
        },
        styleattr() {
            return {
                wrapper: {
                    // boxShadow:
                    //     this.isActiveBorder && !this.isDragging && !this.block.group
                    //         ? `0 0 0 ${
                    //               this.isEditing || this.isActive
                    //                   ? "1px rgb(var(--primary-color-active))"
                    //                   : ""
                    //           }`
                    //         : "",
                    // outline now handled by CSS ::after on .ecom-block-active (always renders above child content)
                    display:
                        !this.isDragging || !(this.dropTo !== this && this.dragCurrent === this),
                    // pointerEvents: this.isDragMe ? 'none' : '',
                    // marginTop: !this.exporting && !this.data?.advanced?.spacing?.margin?.top ? "1px" : ""
                },
                settings: `display: ${this.over && !this.isDragging ? "inline-block" : "none"}`
            };
        },
        blockAttrs() {
            const attrs = {
                ref: "wrapper",
                class: {
                    // "ecom-flexbox": this.data.blocks && this.isFlexContainer,
                    // isParentRow chỉ dùng cho drag direction (X-axis), không ảnh hưởng animation
                    "ecom-animated": !this.exporting,
                    "ecom-animation":
                        this.data?.group?.advanced?.animation_type ||
                        this.data?.advanced?.animation_type,
                    "ecom-drag-flexbox-row": this.isParentRow && !this.exporting,
                    "ecom-block ecom-core core__block": true,
                    // "ecom-flexbox-col": this.data.name === 'flexContainer',
                    "ecom-width-desktop": this.data.advanced?.['width-max'] === 'custom' && this.data.advanced?.["custom-width"],
                    "ecom-width-mb": this.width_mb,
                    'order-start': this.data?.advanced?.order === 'start',
                    'order-end': this.data?.advanced?.order === 'end',
                    "ecom-block-active": this.isActive || this.isEditing,
                    "ecom-block-isDragPadding":
                        this.isActive && !this.isDragging && !this.block.group,
                    elmspace: !this.data?.advanced?.spacing?.margin?.top,
                    ...this.classes
                },
                "data-core-is": this.exporting ? null : this.block.row
                    ? this.deep === 2
                        ? "block"
                        : "row"
                    : this.block.group
                    ? "group"
                    : "block",
                style: !this.block?.row ? this.styleattr.wrapper : "",
                ...this.attributes
            };

            if (this.scrollingAnimation) {
                attrs["ecom-scrolling-animation"] = this.scrollingAnimation;
            }
            // Ưu tiên lấy từ group.advanced (Slider/element's own settings) trước,
            // fallback về block.data.advanced cho dữ liệu cũ
            const delay = this.data?.group?.advanced?.animation_delay || this.data?.advanced?.animation_delay;
            if (delay) {
                const delayValue = delay.toString().replace(/ms$/, '');
                attrs["ec-delay"] = delayValue || 0;
            }

            return attrs;
        },
        canShowPlaceholder() {
            if(this.dragCurrent?.is === 'column' && this.dragCurrent?.section_id === this.section_id) return false

            return (
                this.control &&
                this.dragCurrent &&
                ((this.dropTo === this &&
                    this.dragCurrent !== this &&
                    this.dragCurrent.$parent.$parent !== this) ||
                    (!this.dropTo &&
                        (this.dragCurrent === this || this.dragCurrent.$parent.$parent === this)))

            );
        },
        placeholderTop() {
            return this.canShowPlaceholder && this.dragPosition === "top";
        },

        placeholderBottom() {
            return (
                this.canShowPlaceholder &&
                this.dragPosition === "bottom"
            );
        }
    },

    //Added by daniel
    updated() {
        if (
            this.block.hasRequestLiquid !== true &&
            Object.keys(this.$refs?.blockElement?.requestShopifyType ?? {}).length > 0 &&
            Object.keys(this.$refs?.blockElement?.liquids ?? {}).length > 0
        ) {
            this.block.hasRequestLiquid = true;
        }
        if (this.data.editOnMounted && this.$refs.blockElement) {
            delete this.data.editOnMounted;
            // this.editBlock();
            this.openPresetLibrary();
        }
    },

    mounted() {
        if (this.data.editOnMounted && this.$refs.blockElement) {
            delete this.data.editOnMounted;
            this.openPresetLibrary();
        }
        //Modify by daniel
        if (
            Object.keys(this.$refs?.blockElement?.requestShopifyType ?? {}).length > 0 &&
            Object.keys(this.$refs?.blockElement?.liquids ?? {}).length > 0
        ) {
            this.block.hasRequestLiquid = true;
        } else if (this.block.hasRequestLiquid === true) {
            // Clear stale flag — element no longer has requestShopifyType + liquids
            this.block.hasRequestLiquid = false;
        }
        if (this.block?.group && !this.block.id) {
            this.block.id = this.$helpers.randid();
        }
        this.instanceStore.register(this.data.id, this);
        this.isMounted = true;
        this.$nextTick(() => {
            setTimeout(() => {
                this.updateGridItemFromContent();
            }, 100);
        });
    },
    watch: {
        "progress.show": function (newVal) {
            if (!newVal && !this.initInGrid) {
                this.initInGrid = true;
                // Chỉ cập nhật lần 2 nếu block có hasRequestLiquid
                if (this.block.hasRequestLiquid) {
                    // Đợi DOM cập nhật xong
                    this.$nextTick(() => {
                        this.canSetTempBlockNull = true;
                        this.updateGridItemFromContent(true);
                    });
                } else {
                    // Nếu không có hasRequestLiquid thì cho phép set tempBlock = null
                    this.canSetTempBlockNull = true;
                }
            }
        }
    },

    methods: {
        overBlock(e) {
            if (!this.isFullScreen) {
                // Tính toán vị trí chuột relative so với block
                this.calculateMousePosition(e);
                this.over = true;

                // Ensure parent column displays border on hover (uses `hovered`, not `over`)
                let col: any = this._column;
                if (col && col.hovered === false) {
                    col.hovered = true;
                }

                // Set placeholder position based on mouse position
                this.updatePlaceholderPosition();

                clearTimeout(this.timmer);
            }
            if (this.isDragging && !this.isFullScreen && this.dragCurrent?.is !== "column") {
                if (this.dropTo !== this) {
                    this.$store.commit("builder/setDropTo", this);
                }
                if (this.section_id && this.$store.getters['builder/sectionDrag'] !== this.section_id) {
                    this.$store.commit("builder/sectionDrag", this.section_id);
                }
            }
        },
        calculateMousePosition(e, refreshRect = true) {
            if (this.$refs.wrapper) {
                // getBoundingClientRect ép browser sync layout — không được gọi trên
                // mỗi mousemove. Mouseenter luôn lấy rect mới; mousemove liên tục trên
                // cùng block chỉ refresh tối đa 10 lần/giây (đủ bám theo auto-scroll)
                const now = performance.now();
                if (refreshRect || !this.blockRect || now - (this._blockRectAt || 0) > 100) {
                    this.blockRect = this.$refs.wrapper.getBoundingClientRect();
                    this._blockRectAt = now;
                }
                this.mousePosition = {
                    x: e.clientX - this.blockRect.left,
                    y: e.clientY - this.blockRect.top
                };
            }
        },

        // Method mới để cập nhật vị trí placeholder
        updatePlaceholderPosition() {
            if (this.blockRect) {
                if (this.isParentRow) {

                    const relativeX = this.mousePosition.x / this.blockRect.width;

                    if (relativeX <= 0.5) {
                        this.dragPosition = "top";
                        this.placeholder = "top";
                    } else {
                        this.dragPosition = "bottom";
                        this.placeholder = "bottom";
                    }
                } else {
                    const relativeY = this.mousePosition.y / this.blockRect.height;
                    if (relativeY <= 0.5) {
                        this.dragPosition = "top";
                        this.placeholder = "top";
                    } else {
                        this.dragPosition = "bottom";
                        this.placeholder = "bottom";
                    }
                }
                if (this.dropPos !== this.placeholder) {
                    this.$store.commit("builder/setDropPos", this.placeholder);
                }
            }
        },
        onBlockMouseMove(e) {
            if (!this.isFullScreen && this.over && this.isDragging && this.dragCurrent?.is !== "column") {
                this.calculateMousePosition(e, false);
                this.updatePlaceholderPosition();
            }
        },
        updateGridItemFromContent(isUpdate = false) {
            if (
                !this.$refs.blockElement ||
                (this.$refs.blockElement && !this.$refs.blockElement.$el) ||
                (this.data.layouts && !this.data.layouts.modify)
            ) {
                if (!this.$refs.blockElement) {
                    // Extension
                    this.$emit("update-size", {
                        id: this.data.id,
                        width: 400,
                        height: 50,
                        isUpdate: false,
                        canSetTempBlockNull: true
                    });
                }
                return;
            }
            let element = this.$refs.blockElement.$el;
            if (!element) return;
            // Vue 3: với multi-root component, $el có thể là text/comment node
            // Tìm element thực sự có getBoundingClientRect
            if (!(element instanceof Element)) {
                element = element.nextElementSibling || element.parentElement?.querySelector(':first-child');
            }
            if (!element || typeof element.getBoundingClientRect !== 'function') return;
            const rect = element.getBoundingClientRect();
            // Gửi sự kiện với id của block
            this.$emit("update-size", {
                id: this.data.id,
                width: Math.ceil(rect.width),
                height: Math.ceil(rect.height),
                isUpdate: isUpdate,
                canSetTempBlockNull: this.canSetTempBlockNull || !this.block.hasRequestLiquid
            });
        },

        findGridParent() {
            let parent = this.$parent;
            while (parent && parent.$options.name !== "Grid") {
                parent = parent.$parent;
            }
            return parent;
        },
        startDragPadding(e, name) {
            this.position = e["clientY"];
            this.paddingPosition = name;
            this.idoc().onmouseup = this.onMouseUp;
            this.idoc().onmousemove = this.onMouseMove;
            //this.$store.commit('builder/setActiveElement', this);
        },
        onMouseMove(e) {
            this.$store.commit("builder/setIsDragPadding", this.data.id);
            let element = this.$refs?.blockElement,
                $el = element?.$el?.parentElement,
                advance = Object.assign({}, this.$refs?.blockElement?.data?.advanced);
            if(this.data.blocks && this.isFlexContainer){
                $el = $el.querySelector('.ec-flex-wp');
            }
            if (!$el) return false;
            let padding =
                this.paddingPosition == "bottom"
                    ? advance?.spacing?.padding?.bottom
                    : advance?.spacing?.padding?.top;
            let space = 0,
                result = "";
            padding = padding ? parseInt(padding.replace(/[^0-9.]/g, "")) : 0;

            this.idoc().body.style.cursor = "ns-resize";

            let newP = e["clientY"];
            space = newP - this.position;

            if (Math.abs(space) > 3) {
                this.isDrag = true;
                this.paddingCurrentVal = padding;
                let padding_current = space + padding >= 0 ? space + padding : 0;
                if (this.paddingPosition == "bottom") {
                    //$el.style.paddingBottom = (padding_current) + 'px';
                    $el.style.setProperty("padding-bottom", padding_current + "px", "important");
                } else {
                    //$el.style.paddingTop = Math.abs(padding_current) + 'px';
                    $el.style.setProperty(
                        "padding-top",
                        Math.abs(padding_current) + "px",
                        "important"
                    );
                }
                this.paddingCurrentVal = result = Math.abs(padding_current);
            }

            this.space = result == 0 || result == "" ? 0 : result + "px";
        },
        onMouseUp() {
            const currentScreen = this.currentScreen(),
                currentScreenName = currentScreen.name == "desktop" ? "" : currentScreen.name,
                spacing_res = currentScreenName ? "spacing__" + currentScreenName : "spacing";

            const element = this.$refs?.blockElement,
                $el = element?.$el?.parentElement,
                advance = Object.assign({}, this.$refs?.blockElement?.data?.advanced);

            if (!$el) return false;
            if (!advance.hasOwnProperty(spacing_res)) {
                advance[spacing_res] = {
                    padding: {}
                };
            } else if (!advance[spacing_res].hasOwnProperty("padding")) {
                advance[spacing_res].padding = {};
            }

            const space = this.space;
            this.space = 0;

            if (this.paddingPosition == "bottom") {
                advance[spacing_res].padding.bottom = space;
            } else {
                advance[spacing_res].padding.top = space;
            }

            Object.assign(this.$refs?.blockElement.data.advanced, advance);

            setTimeout(() => {
                $el.style.paddingBottom = null;
                $el.style.paddingTop = null;
            }, 1000);
            this.paddingPosition = "";
            this.paddingCurrentVal = 0;
            this.isDrag = false;
            this.idoc().body.style.cursor = "default";
            this.idoc().onmouseup = null;
            this.idoc().onmousemove = null;
            this.$store.commit("builder/setIsDragPadding", "");
        },
        outBlock() {
            if (!this.isFullScreen) {
                if (this._group) {
                    this._group.over = true;
                } else if (this._column) {
                    this._column.over = true;
                    if (this._row) {
                        this._row.over = true;
                    } else if (this._section) {
                        this._section.over = true;
                    }
                }
                clearTimeout(this.timmer);
                this.timmer = setTimeout(() => {
                    this.over = false;
                    //this.dragPosition = "top";
                }, 50);
            }
        },
        duplicate() {
            let height = this.$refs?.wrapper?.offsetHeight ?? 0,
                clone = this.cloneData();

            if (clone.title) {
                clone.title = clone.title.replace(/\(([\d]*)\)|$/, (...m) => {
                    if (m[1]) {
                        return "(" + (parseInt(m[1]) + 1) + ")";
                    } else {
                        return "(1)";
                    }
                });
            }
            const { parent_id, index } = getIdParentAndIndex(this);
            this.$store.dispatch("history/addStack", {
                type: "Block",
                data: clone,
                section_id: this.section_id,
                action: "duplicated",
                parent_id: parent_id,
                index: index + 1
            });
            this.stack.splice(index + 1, 0, clone);
            this.scroll(height);
        }
    }
};
</script>